@Component("leavePolicy-handler")
@ProcessingGroup("leavePolicy-processing-group")
public class LeavePolicyEventHandler {
	
	// core constructor
	LeavePolicyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLeavePolicyEvent
     */
    @EventHandler
    public void handle( CreateLeavePolicyEvent event) {
        entityManager.persist(new LeavePolicy(event.getLeavePolicyId(), event.getName(), event.getAccrualRate(), event.getCarryoverAllowed(), event.getMaxBalance(), event.getOrganization(), event.getLeaveRequests(), event.getLeaveCategory(), event.getAccrualUnit()));
    }

    /*
     * @param	event UpdateLeavePolicyEvent
     */
    @EventHandler
    public LeavePolicy handle( UpdateLeavePolicyEvent event) {
    	entityManager.merge(new LeavePolicy(event.getLeavePolicyId(), event.getName(), event.getAccrualRate(), event.getCarryoverAllowed(), event.getMaxBalance(), event.getOrganization(), event.getLeaveRequests(), event.getLeaveCategory(), event.getAccrualUnit()));
    }
    
    /*
     * @param	event DeleteLeavePolicyEvent
     */
    @EventHandler
    public void on( DeleteLeavePolicyEvent event) {
    	LeavePolicy entity = new LeavePolicy();
   
    	// ------------------------------------------
    	// apply the LeavePolicyId
    	// ------------------------------------------
    	entity.setLeavePolicyId( event.getLeavePolicyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LeavePolicyRepository leavePolicyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LeavePolicyEventHandler.class.getName());

}
